,&quot;SpecialSerializationConditions&quot;:null,&quot;EntityName&quot;:null,&quot;Fields&quot;:null,&quot;RemoveFieldNames&quot;:false,&quot;UseFormulas&quot;:false,&quot;Criteria&quot;:null,&quot;Pattern&quot;:&quot;PensiiAlimentare_[GetOrSession:MonthV]_[GetOrSession:YearV]_[GetOrSession:BranchV]&quot;,&quot;FilePassword&quot;:null,&quot;WorksheetPassword&quot;:null,&quot;Folder&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:null},&quot;StoreRelativeURL&quot;:null,&quot;StorePhysicalPath&quot;:null,&quot;StoreLinkClick&quot;:&quot;ExcelUrl&quot;,&quot;DisableForceDownload&quot;:false},&quot;Metadata&quot;:{&quot;PAP_InternalIdentifier&quot;:&quot;Button.Export.ExportXlsx&quot;},&quot;HasActionParameters&quot;:true}},{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;d0dc8b52-2b1d-4c1f-816c-625958fb3b96&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;RedirectToUrl&quot;,&quot;Condition&quot;:null,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:1,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;Url&quot;:&quot;[ExcelUrl]&quot;,&quot;ForceDownload&quot;:true,&quot;EscapeUrl&quot;:false,&quot;OpenInPopup&quot;:false,&quot;PopupTitle&quot;:null,&quot;OpenInNewTab&quot;:false},&quot;Metadata&quot;:{&quot;PAP_InternalIdentifier&quot;:&quot;Button.Export.RedirectUrl&quot;},&quot;HasActionParameters&quot;:true}}],&quot;BulkActionsAfter&quot;:[],&quot;ItemActions&quot;:[],&quot;OnItemClickActionStackId&quot;:-1,&quot;OnBulkClickActionStackId&quot;:-1,&quot;OnBulkClickAfterActionStackId&quot;:-1,&quot;Url&quot;:&quot;&amp;amp;buttonName=ExportPensiiAlimentare&quot;,&quot;ModuleId&quot;:906,&quot;AutoName&quot;:true,&quot;Name&quot;:&quot;ExportPensiiAlimentare&quot;,&quot;Title&quot;:&quot;Export Pensii Alimentare&quot;,&quot;Help&quot;:&quot;Export&quot;,&quot;ShowCondition&quot;:&quot;([HasRole:Admins] || [HasRole:CitizenDevelopers] || [HasRole:Low-CodeEngineer] || [HasRole:Managers] || [HasRole:Payroll_Operator] || [HasRole:Users])&quot;,&quot;IsEnabled&quot;:false,&quot;Metadata&quot;:{&quot;PAP_InternalIdentifier&quot;:&quot;Button.Export&quot;},&quot;Type&quot;:&quot;GridButton&quot;,&quot;OrderIndex&quot;:1,&quot;CssClass&quot;:&quot;link&quot;,&quot;CustomCssClass&quot;:null,&quot;IconClass&quot;:null,&quot;FaIconClass&quot;:null,&quot;PermissionAllUsers&quot;:false,&quot;PermissionsExportJson&quot;:&quot;[\&quot;Users\&quot;,\&quot;Admins\&quot;,\&quot;Citizen Developers\&quot;,\&quot;Low-Code Engineer\&quot;,\&quot;Managers\&quot;,\&quot;Payroll_Operator\&quot;]&quot;,&quot;Permissions&quot;:[9,6,7,5,8,13],&quot;AskForConfirmation&quot;:false,&quot;ConfirmationMessage&quot;:null,&quot;ConfirmationOk&quot;:null,&quot;ConfirmationCancel&quot;:null,&quot;JsCode&quot;:null,&quot;IsClientButton&quot;:false,&quot;ButtonGroupId&quot;:null,&quot;ButtonGroupName&quot;:null,&quot;Id&quot;:0,&quot;EnableCondition&quot;:null,&quot;IsDeleted&quot;:false},{&quot;EnableSelection&quot;:false,&quot;RequiresSelection&quot;:false,&quot;RequiresData&quot;:false,&quot;ShowCount&quot;:false,&quot;SumColumn&quot;:null,&quot;SumMode&quot;:&quot;Default&quot;,&quot;SumCoefficient&quot;:null,&quot;TextBeforeSum&quot;:null,&quot;TextAfterSum&quot;:null,&quot;ConfirmationPosition&quot;:&quot;centered&quot;,&quot;VerticalPosition&quot;:&quot;Top&quot;,&quot;HorizontalPosition&quot;:&quot;Right&quot;,&quot;BulkActions&quot;:[{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;22c556a5-6ec2-47ab-8c17-a7acee7b666b&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;RunSql&quot;,&quot;Condition&quot;:null,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:0,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:null,&quot;QueryTimeout&quot;:null,&quot;SqlQuery&quot;:&quot;-- 1. Șterge doar ce e preluat\nDELETE FROM app.PensieAlimentara\nWHERE \n    Luna = @Luna\n    AND Anul = @Anul\n    AND CodSucursala = @CodSucursala\n    AND StatusCalculTaxe = 5;\n\n-- 2. Insert din luna anterioară (FĂRĂ taxe)\nINSERT INTO app.PensieAlimentara (\n    Marca,\n    Destinatar,\n    Adresa,\n    Rata,\n    Rest,\n    Taxa,\n    Taxam,\n    Nrc,\n    Luna,\n    Anul,\n    CodSucursala,\n    StatusCalculTaxe,\n    CreatedBy,\n    CreatedDate,\n    LastModifiedBy,\n    LastModifiedDate\n)\nSELECT \n    p.Marca,\n    p.Destinatar,\n    p.Adresa,\n    p.Rata,\n    p.Rest,\n\n    --  NU preluăm taxe\n    NULL AS Taxa,\n    NULL AS Taxam,\n\n    p.Nrc,\n\n    @Luna,\n    @Anul,\n    @CodSucursala,\n\n    5,\n\n    ISNULL(p.CreatedBy, @UserId),\n    ISNULL(p.CreatedDate, GETDATE()),\n    @UserId,\n    GETDATE()\n\nFROM app.PensieAlimentara p\n\nWHERE \n    p.CodSucursala = @CodSucursala\n\n    AND p.Luna = CASE \n                    WHEN @Luna = 1 THEN 12\n                    ELSE @Luna - 1\n                 END\n                 \n    AND p.Anul = CASE \n                    WHEN @Luna = 1 THEN @Anul - 1\n                    ELSE @Anul\n                 END\n\n    AND NOT EXISTS (\n        SELECT 1 \n        FROM app.PensieAlimentara x\n        WHERE \n            x.Marca = p.Marca\n            AND x.Luna = @Luna\n            AND x.Anul = @Anul\n            AND x.CodSucursala = @CodSucursala\n    )&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;},{&quot;value&quot;:&quot;[GetOrSession:UserId]&quot;,&quot;name&quot;:&quot;UserId&quot;}],&quot;OutputTokenName&quot;:null,&quot;ExtractColumns&quot;:null,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false,&quot;UseTransactions&quot;:true},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}},{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;336dadd4-172b-4dd1-bb8c-6b7b45d2cc6b&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;RefreshGrid&quot;,&quot;Condition&quot;:null,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:1,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;ModuleId&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;f897370f-a50b-4680-bb56-33079695e9f6&quot;}},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}},{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;b84e4e32-798d-49b1-9154-40a1642aae7c&quot;,&quot;Description&quot;:&quot;Preluare date luna anterioara EFECTUATA&quot;,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;ShowToast&quot;,&quot;Condition&quot;:&quot;[Helper:TokenStatusCalculTaxePostale] == 1&quot;,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:2,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;Heading&quot;:null,&quot;Message&quot;:&quot;&amp;lt;p&amp;gt;Datele din luna anterioara au fost deja preluate.&amp;lt;/p&amp;gt;&quot;,&quot;Icon&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;warning&quot;},&quot;BgColor&quot;:&quot;#2d88a6&quot;,&quot;Transition&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;slide&quot;},&quot;AllowToastClose&quot;:true,&quot;CallBackJsCode&quot;:null,&quot;HideTime&quot;:&quot;10000&quot;,&quot;Stack&quot;:&quot;1&quot;,&quot;ToastPosition&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;mid-center&quot;},&quot;TextAlignment&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;left&quot;},&quot;ShowLoader&quot;:true,&quot;LoaderColor&quot;:&quot;#FFFF00&quot;},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}}],&quot;BulkActionsAfter&quot;:[],&quot;ItemActions&quot;:[],&quot;OnItemClickActionStackId&quot;:-1,&quot;OnBulkClickActionStackId&quot;:-1,&quot;OnBulkClickAfterActionStackId&quot;:-1,&quot;Url&quot;:&quot;&amp;amp;buttonName=PreluareDateLunaAnterioara&quot;,&quot;ModuleId&quot;:906,&quot;AutoName&quot;:true,&quot;Name&quot;:&quot;PreluareDateLunaAnterioara&quot;,&quot;Title&quot;:&quot;Preluare Date Luna Anterioara&quot;,&quot;Help&quot;:null,&quot;ShowCondition&quot;:&quot;&quot;,&quot;IsEnabled&quot;:false,&quot;Metadata&quot;:{},&quot;Type&quot;:&quot;GridButton&quot;,&quot;OrderIndex&quot;:2,&quot;CssClass&quot;:&quot;primary&quot;,&quot;CustomCssClass&quot;:null,&quot;IconClass&quot;:null,&quot;FaIconClass&quot;:null,&quot;PermissionAllUsers&quot;:true,&quot;PermissionsExportJson&quot;:&quot;[]&quot;,&quot;Permissions&quot;:[],&quot;AskForConfirmation&quot;:true,&quot;ConfirmationMessage&quot;:&quot;Esti sigur ca vrei sa preiei PENSIILE ALIMENTARE din luna anterioara?&quot;,&quot;ConfirmationOk&quot;:&quot;Da, sunt sigur(a).&quot;,&quot;ConfirmationCancel&quot;:&quot;Nu, nu sunt sigur(a).&quot;,&quot;JsCode&quot;:null,&quot;IsClientButton&quot;:false,&quot;ButtonGroupId&quot;:null,&quot;ButtonGroupName&quot;:null,&quot;Id&quot;:0,&quot;EnableCondition&quot;:&quot;&quot;,&quot;IsDeleted&quot;:false},{&quot;EnableSelection&quot;:false,&quot;RequiresSelection&quot;:false,&quot;RequiresData&quot;:false,&quot;ShowCount&quot;:false,&quot;SumColumn&quot;:null,&quot;SumMode&quot;:&quot;Default&quot;,&quot;SumCoefficient&quot;:null,&quot;TextBeforeSum&quot;:null,&quot;TextAfterSum&quot;:null,&quot;ConfirmationPosition&quot;:&quot;centered&quot;,&quot;VerticalPosition&quot;:&quot;Top&quot;,&quot;HorizontalPosition&quot;:&quot;Right&quot;,&quot;BulkActions&quot;:[{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;089dce37-be6d-41ff-bfbf-7c10ecc37577&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;RunSql&quot;,&quot;Condition&quot;:null,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:0,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:null,&quot;QueryTimeout&quot;:null,&quot;SqlQuery&quot;:&quot;;WITH NrMandate AS\n(\n    SELECT COUNT(*) AS Nr\n    FROM app.PensieAlimentara\n    WHERE Anul = @Anul\n      AND Luna = @Luna\n      AND CodSucursala = @CodSucursala\n)\n\nUPDATE p\nSET \n    Taxa =\n        CASE \n            WHEN LEFT(p.CodSucursala,1) IN (&#39;A&#39;,&#39;G&#39;) THEN 0\n\n            WHEN LEFT(p.CodSucursala,1) = &#39;W&#39;\n                 OR nm.Nr &amp;gt; 10 THEN\n                ROUND((p.Rata + ISNULL(p.Rest,0)) * 0.011,0)\n                + ISNULL(t.TaxaInregistrare,0)\n                + CASE WHEN p.PostRestant = 1 \n                       THEN ISNULL(t.TaxaPOSTRESTANT,0)\n                       ELSE 0 END\n\n            ELSE\n                CASE \n                    WHEN (p.Rata + ISNULL(p.Rest,0)) &amp;lt;= 200  THEN 5\n                    WHEN (p.Rata + ISNULL(p.Rest,0)) &amp;lt;= 500  THEN 10\n                    WHEN (p.Rata + ISNULL(p.Rest,0)) &amp;lt;= 1000 THEN 15\n                    ELSE ROUND((p.Rata + ISNULL(p.Rest,0)) * 0.01,0) + 15\n                END\n                + CASE WHEN p.PostRestant = 1 \n                       THEN ISNULL(t.TaxaPOSTRESTANT,0)\n                       ELSE 0 END\n        END,\n\n    Taxam = ISNULL(t.ValoareFormularMandat,0),\n\n    StatusCalculTaxe = 1\n\nFROM app.PensieAlimentara p\nCROSS JOIN NrMandate nm\nCROSS JOIN (SELECT TOP 1 * FROM app.TSTaxaMandatPostal) t\nWHERE p.Anul = @Anul\n  AND p.Luna = @Luna\n  AND p.CodSucursala = @CodSucursala;&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;}],&quot;OutputTokenName&quot;:&quot;taxe&quot;,&quot;ExtractColumns&quot;:null,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false,&quot;UseTransactions&quot;:true},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}},{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;2168547d-9410-4d8b-aecb-bf1ea7e07f7a&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;RefreshGrid&quot;,&quot;Condition&quot;:null,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:1,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;ModuleId&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;f897370f-a50b-4680-bb56-33079695e9f6&quot;}},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}}],&quot;BulkActionsAfter&quot;:[],&quot;ItemActions&quot;:[],&quot;OnItemClickActionStackId&quot;:-1,&quot;OnBulkClickActionStackId&quot;:-1,&quot;OnBulkClickAfterActionSt